mapper.select:
select t.test_id as testId, t.test_name as testName, t.tmpl_id as tmplId, t1.tmpl_name as tmplName, DATE_FORMAT(t.analysis_vdate,'%Y-%m-%d') as analysisVDate, DATE_FORMAT(t.analysis_mdate,'%Y-%m-%d') as analysisMDate, DATE_FORMAT(t.base_date,'%Y-%m-%d') as baseDate, t.test_date as testDate, DATE_FORMAT(t.start_time,'%Y-%m-%d %H:%i:%s') as startTime, t.finished_time as finishedTime, t.exe_status as exeStatus, t.remark as remark, t4.tips_value as openMode, t3.scene_id as sceneId, t3.scene_name as sceneName from STT_STRESS_TEST t left join STT_STRESS_TMPL t1 on t1.tmpl_id=t.tmpl_id left join STT_STRESS_TIPS t2 on t.tmpl_id=t2.tmpl_id --left join STT_STRESS_SCENE t3 on t.test_id=t3.BUSI_ID and t3.stt_busi_type='04'--业务类型是04:压力测试 left join (select sttStrSce.BUSI_ID,sttStrSce.stt_busi_type,sttSce.scene_id,sttSce.scene_name from STT_STRESS_SCENE sttStrSce left join STT_SCENE sttSce on sttStrSce.scene_id = sttSce.scene_id)t3 on t.test_id=t3.BUSI_ID and t3.stt_busi_type='04'--业务类型是04:压力测试 left join stt_scene_tips t4 on t3.scene_id=t4.scene_id and t4.dict_code = 'OPENMODE'--适用产品（开放类型） where t2.dict_code='RISK_TYPE' and t2.tips_value='03'
and t4.tips_value = #{openMode}
and t.exe_status=#{exeStatus}
and DATE_FORMAT(t.base_date,'%Y-%m-%d')>= SUBSTRING(#{baseDate},1,10) and SUBSTRING(#{baseDate},14,21) >= DATE_FORMAT(t.base_date,'%Y-%m-%d')
and DATE_FORMAT(t.analysis_mdate,'%Y-%m-%d')>= SUBSTRING(#{analysisMDate},0,10) and SUBSTRING(#{analysisMDate},14,21) >= DATE_FORMAT(t.analysis_mdate,'%Y-%m-%d')
and DATE_FORMAT(t.start_time,'%Y-%m-%d') >= SUBSTRING(#{testDate},0,10) and SUBSTRING(#{testDate},14,21) >= DATE_FORMAT(t.start_time,'%Y-%m-%d')
and t.test_id in
#{item}
and t3.scene_id in
#{item}
order by t.start_time desc,t.exe_status desc
